    safeCall(() => {
      throw new Error("x");
    });
    safeCall(() => Promise.reject(new Error("x")));
    const fn = vi.fn();
    safeCall(fn, 1, 2);
    expect(fn).toHaveBeenCalledWith(1, 2);
